import{z as c,x as E,o,c as d,q as i,j as r,D as t,d as a,s,S as p,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Repetition / frequency penalty","description":"","frontmatter":{"title":"Repetition / frequency penalty","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/repetition-penalty.md","filePath":"llm/repetition-penalty.md","lastUpdated":1791413859000}'),m={name:"llm/repetition-penalty.md"};function u(A,e,B,h,f,k){const l=E("Mermaid");return o(),d("div",null,[e[2]||(e[2]=i('<h1 id="repetition-frequency-penalty" tabindex="-1">Repetition / frequency penalty <a class="header-anchor" href="#repetition-frequency-penalty" aria-label="Permalink to &quot;Repetition / frequency penalty&quot;">​</a></h1><div class="epigraph"><p>把已经出现过的 token 的 logits 按重复惩罚缩小，可以压住短循环；它改的是逐步打分，不是在序列级减去「重复次数」这一项损失。</p><footer>—— Keskar et al., CTRL: A Conditional Transformer Language Model for Controllable Generation, 2019</footer></div><p><a href="/llm/minp-typical">上一课</a>把 nucleus、\\(\\varepsilon\\)、\\(\\eta\\)、min-\\(p\\) 写成逐步截断再归一化，目标是去掉过度平滑的长尾。缺口是：圈内 token 仍然合法且概率很高，砍长尾帮不上。Holtzman 指出极大似然解码容易锁进重复圈。CTRL 的 repetition penalty 与 API 里的 frequency / presence penalty，看已经写出的上下文，把出现过的 token 从本步 logits 里压下去。本课写这类解码期惩罚：对象是 token 计数，不是语义重复，并与截断、温度的次序纠缠。不重写 min-\\(p\\) 的地板公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归没有显式的「禁止最近 \\(n\\) 个 token」项。重复可以是立刻的（<code>的的的</code>）、短循环的（<code>是的是的是的</code>）、或篇章级的（同一论点换同义词再说一遍）。模型在这些续写上的条件概率往往很高，因为局部连贯、训练语料里也有修辞反复。Nucleus 留下的核里，循环 token 常常仍在头部。束搜索更糟：累计对数概率会奖励能稳定续写的圈。</p><p>若在训练里加覆盖惩罚或对比目标，成本高，且与下游任务纠缠。推理期惩罚的吸引力是：零训练、逐步可调、能立刻打断圈。代价是惩罚对象是 <em>token 身份</em>，不是 <em>重复这一语言现象</em>。功能词、协议要求的闭合括号、代码里必须再次出现的标识符，都会被同一规则误伤。中文与 BPE 还会把「重复」切碎：表面重复的词可能对应不同子词，子词重复却未必是字面重复。</p><h3 id="出现过、出现次数、与「像不像上文」" tabindex="-1">出现过、出现次数、与「像不像上文」 <a class="header-anchor" href="#出现过、出现次数、与「像不像上文」" aria-label="Permalink to &quot;出现过、出现次数、与「像不像上文」&quot;">​</a></h3><p>Presence 只问是否出现过：见过一次与见过二十次同等减分。Frequency 按计数线性（或按实现约定）加码，圈越转越痛。<span class="marginnote">用交通违章打比方：presence 像「违停一次就记一次违章」，不管你停过多少回，记一笔扣固定的分；frequency 像「按次数累加罚款」，第二次比第一次罚得多，第五次比第二次更狠。转圈的文本相当于反复违停，frequency 对它痛得快，presence 则只给一个固定力度的提醒。</span>CTRL 的 repetition penalty 是乘法，作用在 logits 上且对正负分要分开处理，避免把已经为负的 logit 除以大于 \\(1\\) 的因子后变成更接近零——那会反向鼓励重复。三者都不看隐状态相似度；看表示是否塌缩的是 <a href="/llm/contrastive-search">Contrastive Search</a>。把余弦惩罚与频率惩罚当成同一旋钮，调参时会对不上论文曲线。</p><p><span class="marginnote">OpenAI 兼容接口里的 <code>frequency_penalty</code> / <code>presence_penalty</code> 加在 logits 上，通常再进温度与 nucleus。CTRL 论文的 \\(\\theta\\) 是相除。不要把「惩罚 \\(1.2\\)」在两种公式之间互换。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CTRL 的规则针对已生成集合 \\(G\\)。对词表中每个 token \\(i\\)，设原始 logit 为 \\(\\ell_i\\)，惩罚 \\(\\theta\\ge 1\\)。若 \\(i\\in G\\)，则</p> \\[\\ell_i&#39; = \\begin{cases} \\ell_i / \\theta &amp; \\ell_i \\gt 0,\\\\ \\ell_i \\cdot \\theta &amp; \\ell_i \\le 0. \\end{cases} \\]<p>未出现的 token 保持 \\(\\ell_i\\)。正 logit 被缩小，负 logit 被拉得更负，重复项无论在 softmax 前的哪一侧都被抑制。\\(\\theta=1\\) 关闭惩罚。<span class="marginnote">代入数字看一眼：取 \\(\\theta=1.2\\)，某个重复 token 的 logit 是 \\(6\\)，除以 \\(1.2\\) 后变 \\(5\\)，softmax 里它的优势被削掉一截；若另一个重复 token 的 logit 是 \\(-3\\)，则乘以 \\(1.2\\) 变 \\(-3.6\\)，被推得更远。假如不分符号直接都做除法，\\(-3/1.2=-2.5\\)，反而离零更近、概率变高——惩罚变成了奖励，这正是分支的意义。</span>常见取值在 \\(1.05\\)–\\(1.3\\)；过大时模型开始回避任何复现的内容词，叙述会跳题。</p><p>Presence / frequency 是加法族。设 \\(c_i\\) 为截至当前的出现次数，\\(p,f\\) 为两个标量，</p> \\[\\ell_i&#39; = \\ell_i - p\\cdot \\mathbf{1}_{c_i\\gt 0} - f\\cdot c_i. \\]<p>\\(p\\) 打击「再用一次已经用过的词」，\\(f\\) 打击高频词。许多实现还把窗口限制在最近 \\(W\\) 个 token，避免开篇专有名词在全文里永远减分。计数是 token 级还是解码后的字符串级，要写进协议：前者实现简单，后者更接近用户看到的「重复了这句话」。</p><h3 id="与截断采样的叠放顺序" tabindex="-1">与截断采样的叠放顺序 <a class="header-anchor" href="#与截断采样的叠放顺序" aria-label="Permalink to &quot;与截断采样的叠放顺序&quot;">​</a></h3><p>惩罚改 logit，截断看的是改完之后的分布。先惩罚再 nucleus，核里已经少了重复项，采样不太容易回到圈里；先 nucleus 再惩罚，可能把质量已经集中在少数重复 token 上，惩罚后再归一化会把剩下的核扭曲得更厉害，甚至只剩功能词。Min-\\(p\\) 的 \\(p_{\\max}\\) 若在惩罚之后计算，门槛会随「被压下去的冠军」一起下降，等于自动给非重复项放行，这往往是想要的。投机解码必须在草稿与目标上用同一套惩罚与同一段已接受前缀计数，否则接受比比较的不是同一个条件分布。</p>',18)),(o(),r(p,null,{default:t(()=>[s(l,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTX%5B%22%E5%B7%B2%E7%94%9F%E6%88%90%20token%20%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20PEN%5B%22repetition%20%2F%20frequency%20%2F%20presence%22%5D%0A%20%20L%5B%22%E5%8E%9F%E5%A7%8B%20logits%22%5D%20--%3E%20PEN%0A%20%20PEN%20--%3E%20TMP%5B%22%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20TMP%20--%3E%20CUT%5B%22nucleus%20%2F%20min-p%20%2F%20%CE%B5%22%5D%0A%20%20CUT%20--%3E%20S%5B%22%E9%87%87%E6%A0%B7%22%5D%0A%20%20S%20--%3E%20CTX%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n("h2",{id:"机制",tabindex:"-1"},[a("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=n("p",null,[a("重复圈能自我维持，是因为条件分布在局部 \\(n\\) 元上峰值极高，采样或贪心都会再选同一个续写。乘法或加法惩罚把这个峰值从本步打分里挖掉，迫使质量流向尚未用过的 token。它不修复表示塌缩：若隐状态已经几乎不变，下一层仍会提出相似的头部，惩罚只是在头部里改排序。因此长循环有时会变成近义循环——字面 token 不再重复，语义仍在原地打转。Contrastive Search 用隐状态相似度直接打这项，频率惩罚做不到。"),n("span",{class:"marginnote"},"常见误区：看到重复 \\(n\\) 元率下降就以为循环治好了。惩罚可能只是把「是的是的」改写成「对的、没错、确实如此」，字面统计变好，内容仍在原地转圈。评测要同时报主题一致性或语义相似度，单看 \\(n\\) 元率会选出跳题或换汤不换药的赢家。")],-1)),(o(),r(p,null,{default:t(()=>[s(l,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%B7%B2%E5%87%BA%E7%8E%B0%20token%20%E7%9A%84%E5%8E%9F%E5%A7%8B%20logit%22%5D%20--%3E%20B%7B%22%E7%AC%A6%E5%8F%B7%E5%88%86%E6%94%AF%22%7D%0A%20%20B%20--%20%22%E6%AD%A3%3A%20%E2%84%93%20%C3%B7%20%CE%B8%22%20--%3E%20C%5B%22logit%20%E5%8F%98%E5%B0%8F%20%E6%A6%82%E7%8E%87%E8%A2%AB%E5%8E%8B%22%5D%0A%20%20B%20--%20%22%E9%9D%9E%E6%AD%A3%3A%20%E2%84%93%20%C3%97%20%CE%B8%22%20--%3E%20D%5B%22logit%20%E6%9B%B4%E8%B4%9F%20%E6%A6%82%E7%8E%87%E4%B9%9F%E8%A2%AB%E5%8E%8B%22%5D%0A%20%20E%5B%22%E8%8B%A5%E4%B8%8D%E5%88%86%E6%94%AF%3A%20%E8%B4%9F%20logit%20%E4%B9%9F%E9%99%A4%E4%BB%A5%20%CE%B8%22%5D%20--%3E%20F%5B%22%E6%9B%B4%E6%8E%A5%E8%BF%91%200%20%E5%8F%8D%E5%90%91%E9%BC%93%E5%8A%B1%E9%87%8D%E5%A4%8D%22%5D%0A%20%20C%20--%3E%20G%5B%22softmax%20%E5%89%8D%E4%B8%A4%E4%BE%A7%E9%83%BD%E8%A2%AB%E6%8A%91%E5%88%B6%22%5D%0A%20%20D%20--%3E%20G%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=i('<p>功能词与标点的出现次数天然高。Frequency 会对 <code>的</code>、<code>,</code>、<code>the</code> 持续加码，句子被逼得越来越短、越来越不像人话。Presence 对开篇出现的主题词同样不友好：一篇讲「注意力」的文章会越来越不敢再写这两个字。窗口化、只惩罚非停用词、或只惩罚重复的 <em>短语</em> 而不是单 token，都是在承认 <strong>token 计数是重复的粗糙代理</strong>。代码与 JSON 里标识符必须复现，全局频率惩罚会把合法程序变成改名竞赛；这类任务应关惩罚，改用语法约束。</p><p><span class="marginnote">长度归一化与重复惩罚解决的不是同一偏置。前者补偿「更长序列对数和更负」；后者补偿「局部条件分布爱循环」。束搜索里可以两项都加，但目标函数已经不是 \\(\\log\\pi\\)，不要再声称 MAP。</span></p><h3 id="中文与子词把「重复」切碎" tabindex="-1">中文与子词把「重复」切碎 <a class="header-anchor" href="#中文与子词把「重复」切碎" aria-label="Permalink to &quot;中文与子词把「重复」切碎&quot;">​</a></h3><p>BPE 下「重复重复」可能是两个相同 token，也可能是 <code>重</code>+<code>复</code> 的两次。只按 token 计数会漏掉跨 token 的字面重复，也会把必须成对出现的子词当成重复。解码后再做字符串级 \\(n\\) 元惩罚更接近阅读感受，但流式输出时要缓存足够的尾巴才能判定，且与 <a href="/llm/stop-sequences">stop sequences</a> 一样存在「部分匹配还不能提交」的问题。服务实现若只在 <code>input_ids</code> 上做 <code>unique</code>，应在文档里写明，避免产品与评测各打各的。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>惩罚不是多样性算法。它减少已见 token 的再采用率，不增加未见表征的覆盖；温度与截断仍然决定能从多宽的核里跳出去。安全过滤应放在最终字符串：惩罚可能把拒绝套话打散成新的违规说法，也可能把必须重复的安全声明压掉。翻译与摘要需要对齐源文中的反复用词，默认开频率惩罚会系统性漏译。</p><p>CTRL 的 \\(\\theta\\) 对正负 logit 分支，是为了 softmax 前的符号；若先把 logits 减最大值再惩罚，符号会变，必须在原始 logit 上做。加法惩罚与很大的 \\(f\\) 可以把整行打成很大的负数，随后 softmax 由数值最大的「不太负」的项主导，表现为突然插入罕见词。这不是创意，是分布被推到训练流形之外。</p><p>不要用重复惩罚去替代 <a href="/llm/mirostat">Mirostat</a> 或 typical 采样。前者控的是逐步惊奇度，后者控的是信息量是否靠近熵；重复是序列统计。评测退化时同时报重复 \\(n\\) 元率与主题一致性，只报不重复会选出跳题的赢家。</p><p><span class="marginnote">出处以 Keskar et al., <em>CTRL</em>, 2019 的 repetition penalty 为主；frequency/presence 是随后服务 API 的加法变体，以各厂商文档为准，不要回溯成 CTRL 公式。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重复惩罚在解码期改已出现 token 的 logits，打断短循环，不改变训练分布。</li><li>CTRL 用按符号分支的乘法 \\(\\theta\\)；API 常用 presence（是否出现）与 frequency（出现次数）的加法项。</li><li>惩罚对象是 token 计数，不是语义重复；功能词、代码标识符、主题词会被误伤。</li><li>与温度、nucleus、min-\\(p\\) 的次序会改变核的形状，必须写入采样协议。</li><li>隐状态塌缩导致的近义反复，需要对比搜索一类表示级惩罚，仅靠频率不够。</li><li>子词与流式输出会让「重复」的定义在 token 级与字符串级之间漂移。</li><li>出处：Keskar et al., <em>CTRL: A Conditional Transformer Language Model for Controllable Generation</em>, 2019。退化现象的对照见 Holtzman et al., ICLR 2020。</li></ul>',11))])}const C=c(m,[["render",u]]);export{_ as __pageData,C as default};
